package net.officefloor.hq.app.period;

import java.util.Map;

/** A sheet's period: its name and its from- and to-date (yyyy-mm-dd), both inclusive, whether it is
 *  closed, the due-total fixed when it was closed (two decimals; null while open), and each person's
 *  due-total for it fixed then, by person id (empty while open), and whether it is soft-closed (not closed, but its
 *  due-total and each person's due-total fixed as when closed; claims whose due-by falls inside it can still be changed). */
public record Period(long id, String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> personTotals, boolean softClosed) {
}
package net.officefloor.hq.app.period;

public record PeriodRequest(String name, String from, String to) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;

/** A validated period form: the trimmed name and its from- and to-date (from on or before to). */
public record PeriodInput(String name, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the period form: the name is required (no spaces, as it names the period's row and audit
 *  field), the from- and to-date are yyyy-mm-dd and from is on or before to. */
public class ValidatePeriod {
    public void validate(@RequestBody PeriodRequest request, Out<PeriodInput> period) throws BadRequestException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new BadRequestException("name is required");
        }
        if (name.chars().anyMatch(Character::isWhitespace)) {
            throw new BadRequestException("name must not contain spaces");
        }
        if (name.length() > 500) {
            throw new BadRequestException("name is too long");
        }
        LocalDate from = date(request.from(), "from-date");
        LocalDate to = date(request.to(), "to-date");
        if (from.isAfter(to)) {
            throw new BadRequestException("from-date must be on or before to-date");
        }
        period.set(new PeriodInput(name, from, to));
    }

    private static LocalDate date(String value, String what) throws BadRequestException {
        String v = value == null ? "" : value.trim();
        if (v.isEmpty()) {
            throw new BadRequestException(what + " is required");
        }
        try {
            return LocalDate.parse(v);
        } catch (DateTimeParseException e) {
            throw new BadRequestException(what + " must be yyyy-mm-dd");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SavePeriod {
    public void save(@PathVariable("sheetId") String sheetId, @Val PeriodInput input,
            ServerHttpConnection connection, PeriodRepository repository, Audit audit, Out<Period> period)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        if (repository.named(id, input.name())) {
            throw new BadRequestException("a period named " + input.name() + " is already on the sheet");
        }
        if (repository.overlaps(id, input.from(), input.to())) {
            throw new BadRequestException("the period overlaps another period");
        }
        Period saved = repository.add(id, input.name(), input.from(), input.to());
        audit.record("PERIOD_ADDED sheet=" + id + " by=" + by + " period=" + saved.name() + " from=" + saved.from()
                + " to=" + saved.to());
        period.set(saved);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class PeriodRepository {

    private static final RowMapper<Period> ROW = (rs, i) -> new Period(rs.getLong("id"), rs.getString("name"),
            rs.getDate("from_date").toLocalDate().toString(), rs.getDate("to_date").toLocalDate().toString(),
            rs.getBoolean("closed"), rs.getBigDecimal("closed_total") == null ? null
                    : rs.getBigDecimal("closed_total").setScale(2).toPlainString(), Map.of(),
            rs.getBoolean("soft_closed"));

    private static final String COLUMNS = "id, name, from_date, to_date, closed, closed_total, soft_closed";

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Lock the sheet's row until the transaction commits, so two periods added at once are checked
     *  one after the other; false when there is no such sheet. */
    public boolean lockSheet(String sheetId) {
        return !jdbc.queryForList("SELECT id FROM sheet WHERE id = ? FOR UPDATE", String.class, sheetId).isEmpty();
    }

    /** The sheet's today (yyyy-MM-dd); null when the sheet has none. */
    public String today(String sheetId) {
        List<Date> found = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
        return found.isEmpty() || found.get(0) == null ? null : found.get(0).toLocalDate().toString();
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        List<Period> periods = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? ORDER BY from_date",
                ROW, sheetId);
        Map<Long, Map<String, String>> totals = new HashMap<>();
        jdbc.query("SELECT period_id, person_id, total FROM period_person_total WHERE sheet_id = ? ORDER BY person_id",
                rs -> {
                    totals.computeIfAbsent(rs.getLong("period_id"), k -> new LinkedHashMap<>())
                            .put(Long.toString(rs.getLong("person_id")), rs.getBigDecimal("total").setScale(2).toPlainString());
                }, sheetId);
        return periods.stream().map(p -> new Period(p.id(), p.name(), p.from(), p.to(), p.closed(), p.closedTotal(),
                totals.getOrDefault(p.id(), Map.of()), p.softClosed())).toList();
    }

    /** The sheet's period of this name (exactly); null when there is none. */
    public Period find(String sheetId, String name) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND name = ?", ROW,
                sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The name of the sheet's closed period whose dates contain a date; null when none does. */
    public String closedOn(String sheetId, LocalDate on) {
        List<String> found = jdbc.queryForList("SELECT name FROM period WHERE sheet_id = ? AND closed"
                + " AND from_date <= ? AND to_date >= ?", String.class, sheetId, Date.valueOf(on), Date.valueOf(on));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Close (or soft-close) a period, fixing afresh its due-total and each person's due-total for it (by person id). */
    public void close(String sheetId, long periodId, BigDecimal total, Map<Long, BigDecimal> personTotals, boolean soft) {
        jdbc.update("DELETE FROM period_person_total WHERE period_id = ? AND sheet_id = ?", periodId, sheetId);
        jdbc.update("UPDATE period SET closed = ?, soft_closed = ?, closed_total = ? WHERE id = ? AND sheet_id = ?",
                !soft, soft, total, periodId, sheetId);
        for (Map.Entry<Long, BigDecimal> e : personTotals.entrySet()) {
            jdbc.update("INSERT INTO period_person_total (period_id, sheet_id, person_id, total) VALUES (?, ?, ?, ?)",
                    periodId, sheetId, e.getKey(), e.getValue());
        }
    }

    /** Reopen a closed or soft-closed period, dropping its fixed due-total. */
    public void reopen(String sheetId, long periodId) {
        jdbc.update("DELETE FROM period_person_total WHERE period_id = ? AND sheet_id = ?", periodId, sheetId);
        jdbc.update("UPDATE period SET closed = FALSE, soft_closed = FALSE, closed_total = NULL WHERE id = ? AND sheet_id = ?", periodId,
                sheetId);
    }

    /** Whether the sheet has a period of this name, without regard to case. */
    public boolean named(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name_key = LOWER(?)",
                Integer.class, sheetId, name);
        return n != null && n > 0;
    }

    /** Whether any period of the sheet shares a day with from..to (inclusive). */
    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ?"
                + " AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, Date.valueOf(to), Date.valueOf(from));
        return n != null && n > 0;
    }

    public Period add(String sheetId, String name, LocalDate from, LocalDate to) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(c -> {
            PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setDate(3, Date.valueOf(from));
            ps.setDate(4, Date.valueOf(to));
            return ps;
        }, keys);
        return new Period(keys.getKey().longValue(), name, from.toString(), to.toString(), false, null, Map.of(), false);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeriod {
    public void respond(@Val Period period, ObjectResponse<Period> response) {
        response.send(period);
    }
}

